<script setup>
import { onMounted,onBeforeUnmount,ref,watch } from 'vue'
import { ElMessage,ElMessageBox } from 'element-plus'
import { call } from '../api.js'
import { can } from '../admin/accessPolicy.js'
import VersionDiff from './VersionDiff.vue'
import ApprovalAssets from './ApprovalAssets.vue'
import { compareVersions } from '../admin/versionComparison.js'
const props=defineProps({identity:Object,draft:Object})
const emit=defineEmits(['error','submitted'])
const rows=ref([]),total=ref(0),page=ref(1),status=ref('all'),busy=ref(false),detail=ref(null),drawer=ref(false),title=ref(''),scheduled=ref(null),saving=ref(false),changes=ref([])
const labels={SUBMITTED:'待审核',APPROVED:'已批准 · 等待执行',PUBLISHED:'已发布',REJECTED:'已驳回',CANCELLED:'已撤销',FAILED:'执行失败'}
const modules={config:'玩法规则',audio:'声音工作室',character:'人物工作室'}
const time=value=>value?new Date(value).toLocaleString('zh-CN',{hour12:false}):'批准后尽快发布'
let generation=0,detailGeneration=0
async function load(){const ticket=++generation;busy.value=true;try{const r=await call('GET',`/admin-api/v1/releases?page=${page.value}&size=20&status=${status.value}`);if(ticket===generation){rows.value=r.items;total.value=r.total}}catch(e){if(ticket===generation)emit('error',e)}finally{if(ticket===generation)busy.value=false}}
async function show(row){const ticket=++detailGeneration;detail.value=null;changes.value=[];drawer.value=true;try{const r=await call('GET','/admin-api/v1/releases/'+row.id);if(ticket!==detailGeneration)return;detail.value=r;if(r.module==='config'){const current=await call('GET','/admin-api/v1/config/active');if(ticket===detailGeneration)changes.value=compareVersions(current.settings,r.payload.settings)}}catch(e){if(ticket===detailGeneration)emit('error',e)}}
async function submit(){if(saving.value)return;if(!title.value.trim()){ElMessage.error('请填写发布标题');return}saving.value=true;try{await call('POST','/admin-api/v1/releases',{module:props.draft.module,title:title.value,payload:props.draft.payload,scheduledAt:scheduled.value?+new Date(scheduled.value):0});ElMessage.success('已提交审批，内容已固定；修改需撤销后重新提交');emit('submitted');await load()}catch(e){emit('error',e)}finally{saving.value=false}}
async function decide(action){if(saving.value||!detail.value)return;let note='';try{if(action==='reject'){const r=await ElMessageBox.prompt('填写驳回原因','驳回审批',{inputValidator:v=>!!v?.trim()||'请填写原因'});note=r.value}else await ElMessageBox.confirm(action==='approve'?'批准后将在指定时间执行；执行时仍会核对账号权限和内容版本。':'撤销后不会执行此审批单。',action==='approve'?'批准发布':'撤销审批',{type:'warning'})}catch{return}saving.value=true;try{detail.value=await call('POST',`/admin-api/v1/releases/${detail.value.id}/decision`,{expectedVersion:detail.value.version,action,note});await load()}catch(e){emit('error',e)}finally{saving.value=false}}
watch(()=>props.draft,()=>{title.value=props.draft?.title||'';scheduled.value=null},{immediate:true})
onMounted(load);onBeforeUnmount(()=>{generation++;detailGeneration++})
</script>
<template>
  <section v-if="draft&&can(identity,'release:submit')" class="surface"><h3>提交{{modules[draft.module]}}审批</h3><p class="muted">提交当前内容的固定快照，由另一位具备审批及本模块发布权限的人员审核。后续草稿或生效版本发生变化，执行会失败，不会覆盖新版本。原有直接发布入口按原权限保留。</p><el-form label-position="top"><el-form-item label="发布标题"><el-input v-model="title" maxlength="100" /></el-form-item><el-form-item label="预约时间（本机时区）"><el-date-picker v-model="scheduled" type="datetime" placeholder="留空：批准后尽快发布" /></el-form-item></el-form><el-button type="primary" :loading="saving" @click="submit">提交审批</el-button></section>
  <section class="surface" v-loading="busy"><div class="surface-heading"><h3>发布审批与预约任务</h3><el-button @click="load">刷新</el-button></div><div class="section-toolbar"><el-select v-model="status" aria-label="审批状态" style="width:230px" @change="page=1;load()"><el-option label="全部状态" value="all" /><el-option v-for="(label,key) in labels" :key="key" :label="label" :value="key" /></el-select><span class="muted">每10秒扫描到期任务；服务恢复后继续处理已批准的任务。</span></div><el-table :data="rows"><el-table-column prop="title" label="标题" min-width="190" /><el-table-column label="模块" min-width="110"><template #default="{row}">{{modules[row.module]}}</template></el-table-column><el-table-column label="状态" min-width="180"><template #default="{row}"><el-tag :type="row.status==='FAILED'?'danger':row.status==='PUBLISHED'?'success':'info'">{{labels[row.status]}}</el-tag></template></el-table-column><el-table-column label="计划时间" min-width="180"><template #default="{row}">{{time(row.scheduledAt)}}</template></el-table-column><el-table-column label="操作" width="100"><template #default="{row}"><el-button text @click="show(row)">查看审批</el-button></template></el-table-column></el-table><el-empty v-if="!rows.length&&!busy" description="没有符合条件的审批单" :image-size="60" /><el-pagination v-model:current-page="page" :page-size="20" :total="total" layout="prev,pager,next,total" @current-change="load" /></section>
  <el-drawer v-model="drawer" destroy-on-close title="发布审批详情" size="min(900px,96vw)" @close="detailGeneration++"><template v-if="detail"><h3>{{detail.title}}</h3><p>{{modules[detail.module]}} · {{labels[detail.status]}}</p><p class="muted">提交账号 ID {{detail.submittedBy}} · 审核账号 ID {{detail.approvedBy||'—'}}<br>预约：{{time(detail.scheduledAt)}}</p><el-alert v-if="detail.result" :title="detail.result" :type="detail.status==='FAILED'?'error':'info'" :closable="false" /><VersionDiff v-if="detail.module==='config'" :groups="changes" /><template v-else-if="detail.module==='audio'"><h3>固定音量与绑定</h3><el-descriptions :column="1" border><el-descriptions-item label="音乐 / 音效音量">{{detail.payload.settings.musicVolume}}% / {{detail.payload.settings.effectsVolume}}%</el-descriptions-item><el-descriptions-item v-for="(value,key) in detail.payload.settings.scenes" :key="key" :label="key">{{value.assetId||'静音'}} · {{value.loop?'循环':'单次'}}</el-descriptions-item><el-descriptions-item v-for="(value,key) in detail.payload.settings.effects" :key="key" :label="key">{{value||'静音'}}</el-descriptions-item></el-descriptions></template><template v-else><h3>{{detail.payload.pack.character.name}}</h3><p>人物 ID {{detail.payload.pack.character.id}} · 素材修订 {{detail.payload.revision}} · 基准目录 #{{detail.payload.expectedVersion}}</p><div class="ops-asset-list"><div v-for="(asset,slot) in detail.payload.pack.character.images" :key="slot"><strong>{{slot}}</strong><span>{{asset.width}} × {{asset.height}}</span><small>{{asset.sha256}}</small></div></div></template><ApprovalAssets v-if="detail.module!=='config'" :key="detail.id" :request="detail" @error="emit('error',$event)" /><div class="section-toolbar"><template v-if="detail.status==='SUBMITTED'&&can(identity,'release:approve')&&detail.submittedBy!==identity.user.id"><el-button type="success" :disabled="saving" @click="decide('approve')">批准</el-button><el-button type="danger" :disabled="saving" @click="decide('reject')">驳回</el-button></template><el-button v-if="['SUBMITTED','APPROVED'].includes(detail.status)&&(detail.submittedBy===identity.user.id||can(identity,'release:approve'))" :disabled="saving" @click="decide('cancel')">撤销</el-button></div><p v-if="detail.status==='SUBMITTED'&&detail.submittedBy===identity.user.id" class="muted">提交人不能审核自己的发布，请交由另一位审核人处理。</p></template></el-drawer>
</template>
